<template>
  <div class="optimization">
    <OptimizationHeader :title="title" :name="name" :status="status" />
    <div class="optimization-option">
      <div class="optimization-option__title-box">
        <ButtonUI
          svg="back-arrow-svg"
          buttonClass="btn--second"
          @action="$router.back()"
        />
        <h3 class="optimization-option__title">Поиск дубликатов</h3>
      </div>
      <ul class="optimization-option__form">
        <li class="optimization-option__item">
          <CustomSelect
            v-model="selectPartition"
            placeholder="Автомобили"
            :options="selectPartitions"
            @updateSort="sortCategory"
          />
        </li>
        <li class="optimization-option__item">
          <CustomSelectSearch
            v-if="!dataHistoy"
            v-model="selectedLocation"
            :options="locationOptions"
            @updateSort="sortCity"
          />
        </li>
      </ul>
    </div>
    <div>
      <li
        class="optimization-option__more"
        :class="{ 'optimization-option__more--active': item.status }"
        v-for="(item, index) in duplicatesWithStatus"
        :key="index"
      >
        <div
          class="optimization-option__more-info"
          @click="toggleActive(index)"
        >
          <img
            class="optimization-option__more-svg"
            :class="{
              'optimization-option__more-svg--rotated': item.status,
            }"
            src="@/assets/images/svg/arrow.svg"
            alt="arrow"
          />
          <span class="optimization-option__more-count" v-if="!item.status">{{
            item.value
          }}</span>
          <span v-if="!item.status">{{ item.valueText }}</span>
          <span class="optimization-option__more-title" v-if="!item.status">{{
            item.text
          }}</span>

          <div class="optimization-table__box">
            <CustomTable
              v-if="item.status"
              :ItemRows="itemRow[index]"
              :headerRows="headerRows[index]"
              :lineClamp="5"
              height="120px"
              @slot-clicked="handleButtonClick"
            >
              <template #slot-start="{ item, emitEvent }">
                <div class="table-box__slot">
                  <ButtonUI
                    v-if="!item.option.isActiv"
                    svg="edit-svg"
                    text="создать"
                    buttonClass="btn--error"
                    @click="emitEvent('redact', item)"
                  />
                  <ButtonUI
                    v-if="item.option.isActiv"
                    svg="edit-svg"
                    text="изм."
                    buttonClass="btn--third"
                    @click="emitEvent('redact', item)"
                  />
                  <a :href="item.option.link">{{ item.option.text }}</a>
                </div>
              </template>
            </CustomTable>
          </div>
        </div>
      </li>
      <CustomToast text="error text" :error="true" />
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
// import { useRouter } from 'vue-router';

//доработал роутинг для корректного сбора информации с роута

import OptimizationHeader from '@/components/SEO/OptimizationHeader';
import ButtonUI from '@/components/UI/ButtonUI.vue';
import CustomTable from '@/components/UI/CustomTable.vue';
import CustomSelectSearch from '@/components/UI/CustomSelectSearch';
import CustomSelect from '@/components/UI/CustomSelect';
import CustomToast from '@/components/UI/CustomToast';

// import { useSectionTable } from '@/store/Table/seoSectionTable.js';

import { TESTTABLEDublicate } from '@/const/test/test.js';

import { useQueryParams } from '@/composables/useQueryParams';

import { getRegions } from '@/services/apiClient.js';

// const router = useRouter();

// const sectionTableStore = useSectionTable();

const title = ref('SEO Разделов');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');

const selectPartition = ref({});
const selectPartitions = ref(null);

const selectedLocation = ref('');
const locationOptions = ref([]);
const backendData = [
  { value: '10', text: 'h1', status: false },
  { value: '2', text: 'title', status: false },
  { value: '200', text: 'description', status: false },
  { value: '15', text: 'SEO text', status: false },
  { value: '45', text: 'URL', status: false },
  { value: '150', text: 'content', status: false },
];
const getEnding = (count) => {
  const num = parseInt(count, 10);
  const lastDigit = num % 10;
  const lastTwoDigits = num % 100;

  if (lastTwoDigits >= 11 && lastTwoDigits <= 19) {
    return 'ов';
  }

  switch (lastDigit) {
    case 1:
      return '';
    case 2:
    case 3:
    case 4:
      return 'а';
    default:
      return 'ов';
  }
};
const headerRows = ref(
  backendData.map((item) => [
    {
      name: `${item.value} дубликат${getEnding(item.value)}`,
      width: '40%',
      helper: false,
    },
    {
      name: item.text,
      width: '40%',
      helper: false,
    },
    {
      name: 'SEO',
      width: '220px',
      helper: false,
    },
  ])
);

const duplicatesWithStatus = ref(
  backendData.map((item) => ({
    ...item,
    valueText: `дубликат${getEnding(item.value)}`,
  }))
);

const toggleActive = (index) => {
  duplicatesWithStatus.value[index].status =
    !duplicatesWithStatus.value[index].status;
};

const { queryParams, updateQueryParams } = useQueryParams();
//   buildQueryString,loadQueryParamsFromRoute
const itemRow = TESTTABLEDublicate.main;

const sortCity = (option) => {
  queryParams.value.city_id = option;
  updateQueryParams();
};
const sortCategory = (option) => {
  queryParams.value.section_id = option;
  updateQueryParams();
};

// const getItemRow = async () => {
//   loadQueryParamsFromRoute();
// };

const getlocation = async () => {
  const response = await getRegions();

  locationOptions.value = response;
};

onMounted(() => {
  getlocation();
});
</script>

<style scoped lang="scss">
.optimization {
  margin: 12px 16px;
  width: calc(100% - 32px);
  display: flex;
  flex-direction: column;
  height: calc(100% - 25px);
  @media (max-width: 1024px) {
    width: calc(100% - 40px);
    justify-content: space-between;
    margin-top: 70px;
    height: calc(100vh - 60px);
  }
  &-table__box {
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }
  &-option {
    display: flex;
    flex-direction: column;
    justify-content: space-around;
    border-radius: 4px;
    background-color: #eef9ff;
    margin: 16px 0;
    padding: 12px 24px;
    &__form {
      display: flex;
      gap: 20px;
    }
    &__btn-box {
      display: flex;
      gap: 16px;
      align-items: center;
    }
    &__title-box {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    &__item {
      display: flex;
      align-items: center;
      margin-bottom: 16px;
    }
    &__text-box {
      display: flex;
    }
    &__text {
      color: #787878;
      font-weight: 400;
      font-size: 14px;
      min-width: 150px;
    }
    &__more {
      display: flex;
      align-items: center;
      gap: 200px;
      padding: 8px 8px;
      border-top: 1px solid #d6d6d6;
      border-bottom: 1px solid #d6d6d6;

      &--active {
        border-bottom: none;
        &-info {
          color: #3366ff;
        }
      }
      &-btn {
        display: flex;
        align-items: center;
        gap: 16px;
      }
      &-info {
        display: flex;
        gap: 12px;
        color: #787878;
      }
      &-count {
        color: #3366ff;
        font-weight: 600;
        margin-right: 2px;
      }
      &-svg {
        margin-right: 10px;
        transition: transform 0.3s ease;
        &--rotated {
          transform: rotate(180deg);
        }
      }
    }
  }
  .table-box__slot {
    display: flex;
  }
}
</style>
